import jax
import jax.numpy as jnp
from dataclasses import dataclass, field

params = {"w": jnp.ones((3, 2)), "b": jnp.zeros(2)}

def loss(p, x):
    return jnp.sum(jnp.tanh(x @ p["w"] + p["b"]))

grads = jax.grad(loss)(params, jnp.ones((4, 3)))
print(jax.tree.map(jnp.shape, grads))   # {'b': (2,), 'w': (3, 2)}

new = jax.tree.map(lambda p, g: p - 0.1 * g, params, grads)
print(sum(x.size for x in jax.tree.leaves(new)))   # 8 parameters

@jax.tree_util.register_dataclass
@dataclass
class Linear:
    w: jax.Array
    b: jax.Array
    name: str = field(default="dense", metadata=dict(static=True))

layer = Linear(jnp.ones(2), jnp.zeros(2))
print(jax.tree.leaves(layer))   # [Array([1., 1.], ...), Array([0., 0.], ...)]

import jax
import jax.numpy as jnp

@jax.jit
def bad(x):
    if x.sum() > 0:          # Python bool of a tracer
        return x
    return -x

try:
    bad(jnp.ones(3))
except jax.errors.TracerBoolConversionError:
    print("TracerBoolConversionError")

@jax.jit
def good(x):
    return jnp.where(x.sum() > 0, x, -x)
print(good(jnp.ones(3)))                 # [1. 1. 1.]

rep = jax.jit(lambda x, n: jnp.tile(x, n), static_argnames="n")  # n sets the shape
print(rep(jnp.array([1, 2]), n=3))       # [1 2 1 2 1 2]

print(jax.jit(lambda x: x.shape[0] * 2)(jnp.ones((5, 2))))  # 10: shapes are static

import jax
import jax.numpy as jnp
from jax import lax

@jax.jit
def safe_log(x):
    return lax.cond(x > 0, jnp.log, lambda v: jnp.zeros_like(v), x)
print(safe_log(jnp.e), safe_log(-1.0))      # 1.0 0.0

def cumsum_scan(xs):
    def step(carry, x):
        carry = carry + x
        return carry, carry                  # (new carry, per-step output)
    total, ys = lax.scan(step, 0.0, xs)
    return total, ys
print(cumsum_scan(jnp.array([1.0, 2.0, 3.0])))  # (6.0, [1. 3. 6.])

def power(x, n):
    return lax.fori_loop(0, n, lambda i, acc: acc * x, 1.0)
print(jax.jit(power, static_argnums=1)(2.0, 10))  # 1024.0

print(jax.grad(lambda x: cumsum_scan(x)[0])(jnp.ones(3)))  # [1. 1. 1.]

import jax
import jax.numpy as jnp

def init(key, n_in):
    return {"w": jax.random.normal(key, (n_in,)) * 0.1, "b": jnp.zeros(())}

def loss_fn(params, x, y):
    pred = x @ params["w"] + params["b"]
    return jnp.mean((pred - y) ** 2)

@jax.jit
def train_step(params, x, y, lr=0.1):
    loss, grads = jax.value_and_grad(loss_fn)(params, x, y)
    params = jax.tree.map(lambda p, g: p - lr * g, params, grads)
    return params, loss

key, k_data, k_init = jax.random.split(jax.random.key(0), 3)
x = jax.random.normal(k_data, (256, 3))
y = x @ jnp.array([2.0, -1.0, 0.5]) + 3.0
params = init(k_init, 3)
for step in range(200):
    params, loss = train_step(params, x, y)
print(jnp.round(params["w"], 2), jnp.round(params["b"], 2))  # [ 2. -1.  0.5] 3.0
print(float(loss) < 1e-4)   # True

import jax
import jax.numpy as jnp

@jax.jit
def f(x):
    y = jnp.sin(x) * 2
    jax.debug.print("y = {y}", y=y)     # prints real values at run time
    return y.sum()

f(jnp.array([0.0, jnp.pi / 2]))         # y = [0. 2.]

def bad_log(x):
    return jnp.where(x > 0, jnp.log(x), 0.0)
print(jax.grad(bad_log)(0.0))           # nan: log's gradient is still evaluated

def safe_log(x):
    safe_x = jnp.where(x > 0, x, 1.0)   # sanitise the input first
    return jnp.where(x > 0, jnp.log(safe_x), 0.0)
print(jax.grad(safe_log)(0.0))          # 0.0

with jax.disable_jit():
    print(jax.jit(lambda x: x + 1)(1.0))  # runs eagerly: 2.0

import jax
import jax.numpy as jnp

@jax.custom_jvp
def softplus(x):
    return jnp.logaddexp(x, 0.0)

@softplus.defjvp
def softplus_jvp(primals, tangents):
    (x,), (t,) = primals, tangents
    return softplus(x), jax.nn.sigmoid(x) * t   # stable derivative

print(jax.grad(softplus)(100.0))   # 1.0

@jax.custom_vjp
def clip_grad(x):
    return x                       # identity forward

fwd = lambda x: (x, None)              # output, residuals (none needed)
bwd = lambda _, g: (jnp.clip(g, -1.0, 1.0),)  # tuple: one cotangent per input
clip_grad.defvjp(fwd, bwd)
print(jax.grad(lambda x: 10.0 * clip_grad(x))(2.0))  # 1.0 instead of 10.0

import jax
import jax.numpy as jnp
from jax.ad_checkpoint import print_saved_residuals

def block(x, w):
    return jnp.sin(jnp.sin(x @ w))

def net(x, w):
    for _ in range(3):
        x = block(x, w)
    return x.sum()

ckpt_block = jax.checkpoint(
    block, policy=jax.checkpoint_policies.dots_with_no_batch_dims_saveable)

def net_remat(x, w):
    for _ in range(3):
        x = ckpt_block(x, w)
    return x.sum()

x, w = jnp.ones((4, 4)), jnp.eye(4) * 0.5
print(jnp.allclose(jax.grad(net, 1)(x, w), jax.grad(net_remat, 1)(x, w)))  # True
print_saved_residuals(net, x, w)        # many sin/cos residuals listed
print_saved_residuals(net_remat, x, w)  # fewer: dot_general outputs + inputs
